using System;using System.IO;using Newtonsoft.Json.Linq;using Game.Runtime;
internal static class FixedMapParityControls {
 static string Run(JObject binding,JToken nav,bool candidate){try{if(candidate){SourceCapturedFixedMapInputs.ReadAndDecode(binding,nav,out var n);}else{var n=SourceCapturedFixedMapInputs.Read(binding);var d=Path.GetDirectoryName((string)nav["path"]);GeneratedAuthoredNavigationImporter.Decode(binding,d);}return "SUCCESS";}catch(Exception e){return e.GetType().FullName+"|"+e.Message;}}
 static int Main(string[] args){try{var root=JObject.Parse(File.ReadAllText(args[0]));int count=0; Action<string,Action<JObject>,JToken> test=(name,change,nav)=>{var a=(JObject)root.DeepClone();change(a);var b=(JObject)a.DeepClone();string x=Run(a,nav.DeepClone(),false),y=Run(b,nav.DeepClone(),true);if(x!=y||x=="SUCCESS")throw new Exception(name+" mismatch baseline="+x+" candidate="+y);Console.WriteLine(name+" "+x);count++;};var good=new JObject{["path"]=args[0]};var bad=new JObject{["path"]=new JArray(1)};test("schema-before-nav",x=>x["schema_version"]=2,bad);test("kind-before-nav",x=>x["kind"]="bad",bad);test("flag-before-nav",x=>x["runtime_admitted"]=true,bad);test("context-before-nav",x=>x["metadata_compiler_context"]=JValue.CreateNull(),bad);test("qualification-before-nav",x=>x["configuration_qualification"]=JValue.CreateNull(),bad);test("contract-before-nav",x=>x["capture_contract"]=JValue.CreateNull(),bad);test("target-mismatch",x=>x["target_context"]["operation_map_id"]="bad",good);test("native-hash-mismatch",x=>x["native_readback"]["sha256"]=new string("0"[0],64),good);test("native-path-mismatch",x=>x["native_readback"]["path"]=args[1],good);test("missing-context-file",x=>x["metadata_compiler_context"]["path"]=args[1],good);test("missing-qualification-file",x=>x["configuration_qualification"]["path"]=args[1],good);test("missing-contract-file",x=>x["capture_contract"]["path"]=args[1],good);Console.WriteLine("[FixedMapParityControls] result=Passed checks="+count+" world=False");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
